<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder; use App\Models\{Game,Program,Event,EventAgendaItem,EventBudget,EventExpense};
class EventPlatformSeeder extends Seeder { public function run(): void { $games=collect([['name'=>'Pookalam Challenge','category'=>'Team','description'=>'Teams create a vibrant floral carpet.'],['name'=>'Vadam Vali','category'=>'Outdoor','description'=>'The classic tug of war.'],['name'=>'Musical Chairs','category'=>'Indoor','description'=>'Quick, lively musical game.']])->map(fn($x)=>Game::firstOrCreate(['name'=>$x['name']],$x+['slug'=>str($x['name'])->slug(),'status'=>true])); $program=Program::firstOrCreate(['name'=>'Thiruvathira Dance'],['slug'=>'thiruvathira-dance','category'=>'Cultural','description'=>'A graceful traditional performance.','status'=>true]); $event=Event::firstOrCreate(['name'=>'Onam Celebration 2026'],['event_date'=>'2026-08-28','start_time'=>'10:00','end_time'=>'17:00','venue'=>'Community Hall']); if(!$event->agendaItems()->exists()){ EventAgendaItem::create(['event_id'=>$event->id,'item_type'=>'game','item_id'=>$games[0]->id,'start_time'=>'10:30','end_time'=>'11:15','sequence'=>1,'expense_amount'=>1500]); EventAgendaItem::create(['event_id'=>$event->id,'item_type'=>'program','item_id'=>$program->id,'start_time'=>'12:00','end_time'=>'12:30','sequence'=>2,'expense_amount'=>3000]); } EventBudget::firstOrCreate(['event_id'=>$event->id],['total_budget'=>25000]); EventExpense::firstOrCreate(['event_id'=>$event->id,'title'=>'Sound system'],['category'=>'Production','amount'=>4500]); } }
